package com.ceramiflow.service.workflow;
import com.ceramiflow.domain.StageType; import com.ceramiflow.exception.BusinessException; import org.junit.jupiter.api.*; import static org.junit.jupiter.api.Assertions.*;
class WorkflowStateMachineTest { private final WorkflowStateMachine sm=new WorkflowStateMachine(); @Test void formingToDryingIsValid(){assertDoesNotThrow(()->sm.validateAdvance(StageType.FORMING,StageType.DRYING_REPAIR));} @Test void formingToFiringIsRejected(){assertThrows(BusinessException.class,()->sm.validateAdvance(StageType.FORMING,StageType.FIRING));} @Test void qcToPackagingIsValid(){assertDoesNotThrow(()->sm.validateAdvance(StageType.QC,StageType.PACKAGING));} @Test void completedCannotAdvance(){assertThrows(BusinessException.class,()->sm.next(StageType.COMPLETED));} @Test void reworkToGlazingIsValid(){assertDoesNotThrow(()->sm.validateReworkTarget(StageType.GLAZING));} @Test void reworkToPackagingIsRejected(){assertThrows(BusinessException.class,()->sm.validateReworkTarget(StageType.PACKAGING));} }
